import { parseAddr, toAddr } from "./addr.mjs";

const TOKEN = [
  ["num", /(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/y],
  ["str", /"(?:[^"]|"")*"/y],
  ["fn", /[A-Za-z_][A-Za-z0-9_.]*(?=\s*\()/y],
  ["ref", /\$?[A-Za-z]{1,3}\$?[1-9]\d*(?![A-Za-z0-9_.$])/y],
  ["name", /[A-Za-z_][A-Za-z0-9_.]*/y],
  ["op", /<=|>=|<>|[=<>&+\-*\/^(),:]/y],
];

function tokenize(text) {
  const out = [];
  const ws = /\s*/y;
  let pos = 0;
  for (;;) {
    ws.lastIndex = pos;
    ws.exec(text);
    pos = ws.lastIndex;
    if (pos >= text.length) return out;
    let hit = null;
    for (const [type, re] of TOKEN) {
      re.lastIndex = pos;
      const m = re.exec(text);
      if (m) { hit = { type, text: m[0] }; break; }
    }
    if (!hit) throw new SyntaxError(`unexpected character '${text[pos]}' at ${pos}`);
    out.push(hit);
    pos += hit.text.length;
  }
}

const norm = (t) => { const a = parseAddr(t); return toAddr(a.col, a.row); };

export function parseFormula(text) {
  const toks = tokenize(String(text));
  let i = 0;
  const peekOp = () => (toks[i]?.type === "op" ? toks[i].text : null);
  const expect = (op) => {
    if (peekOp() !== op) throw new SyntaxError(`expected '${op}'`);
    i++;
  };
  const binary = (ops, next) => () => {
    let l = next();
    while (ops.includes(peekOp())) {
      const op = toks[i++].text;
      l = { t: "bin", op, l, r: next() };
    }
    return l;
  };
  const primary = () => {
    const tok = toks[i++];
    if (!tok) throw new SyntaxError("unexpected end of formula");
    switch (tok.type) {
      case "num": return { t: "num", v: Number(tok.text) };
      case "str": return { t: "str", v: tok.text.slice(1, -1).replace(/""/g, '"') };
      case "name": {
        const u = tok.text.toUpperCase();
        if (u === "TRUE" || u === "FALSE") return { t: "bool", v: u === "TRUE" };
        throw new SyntaxError(`unknown name '${tok.text}'`);
      }
      case "ref": {
        const a = norm(tok.text);
        if (peekOp() !== ":") return { t: "ref", addr: a };
        i++;
        const t2 = toks[i++];
        if (t2?.type !== "ref") throw new SyntaxError("bad range");
        const p = parseAddr(a), q = parseAddr(t2.text);
        const addrs = [];
        for (let r = Math.min(p.row, q.row); r <= Math.max(p.row, q.row); r++)
          for (let c = Math.min(p.col, q.col); c <= Math.max(p.col, q.col); c++) addrs.push(toAddr(c, r));
        return { t: "range", addrs };
      }
      case "fn": {
        expect("(");
        const args = [];
        if (peekOp() === ")") i++;
        else {
          for (;;) {
            args.push(cmp());
            if (peekOp() === ",") { i++; continue; }
            expect(")");
            break;
          }
        }
        return { t: "call", name: tok.text.toUpperCase(), args };
      }
      case "op":
        if (tok.text === "(") { const e = cmp(); expect(")"); return e; }
    }
    throw new SyntaxError(`unexpected '${tok.text}'`);
  };
  const unary = () => {
    const op = peekOp();
    if (op === "-" || op === "+") { i++; return { t: "un", op, x: unary() }; }
    return primary();
  };
  const pow = binary(["^"], unary);
  const mul = binary(["*", "/"], pow);
  const add = binary(["+", "-"], mul);
  const cat = binary(["&"], add);
  const cmp = binary(["=", "<>", "<", ">", "<=", ">="], cat);
  const ast = cmp();
  if (i < toks.length) throw new SyntaxError(`unexpected '${toks[i].text}'`);
  return ast;
}

export function refsOf(ast) {
  const seen = new Set();
  const walk = (n) => {
    switch (n.t) {
      case "ref": seen.add(n.addr); break;
      case "range": n.addrs.forEach((a) => seen.add(a)); break;
      case "un": walk(n.x); break;
      case "bin": walk(n.l); walk(n.r); break;
      case "call": n.args.forEach(walk); break;
    }
  };
  walk(ast);
  return [...seen];
}

class Fail { constructor(code) { this.code = code; } }
const isErr = (v) => typeof v === "string" && v.startsWith("#");
const fail = (code) => { throw new Fail(code); };
const chk = (v) => { if (isErr(v)) throw new Fail(v); return v; };

function toNum(v) {
  chk(v);
  if (v === null) return 0;
  if (typeof v === "number") return v;
  if (typeof v === "boolean") return v ? 1 : 0;
  const s = v.trim();
  if (s === "" || !Number.isFinite(Number(s))) fail("#VALUE!");
  return Number(s);
}
const fin = (n) => (Number.isFinite(n) ? n : fail("#NUM!"));

function toText(v) {
  chk(v);
  if (v === null) return "";
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

function toBool(v) {
  chk(v);
  if (v === null) return false;
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v !== 0;
  const u = v.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  return fail("#VALUE!");
}

const rank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

function compare(a, b) {
  if (a === null && b === null) { a = 0; b = 0; }
  else if (a === null) a = b === null ? 0 : typeof b === "number" ? 0 : typeof b === "string" ? "" : false;
  else if (b === null) b = typeof a === "number" ? 0 : typeof a === "string" ? "" : false;
  const ra = rank(a), rb = rank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { a = a.toLowerCase(); b = b.toLowerCase(); }
  return a < b ? -1 : a > b ? 1 : 0;
}

function shift(x, e) {
  const [m, ex] = x.toExponential().split("e");
  return Number(`${m}e${Number(ex) + e}`);
}
function round(x, d) {
  d = Math.trunc(d);
  const r = shift(Math.round(shift(Math.abs(x), d)), -d);
  return x < 0 ? -r : r;
}

export function evaluate(ast, lookup) {
  const ev = (n) => {
    switch (n.t) {
      case "num": case "str": case "bool": return n.v;
      case "ref": return lookup(n.addr);
      case "range": return "#VALUE!";
      case "un": {
        const x = toNum(ev(n.x));
        return n.op === "-" ? -x : x;
      }
      case "bin": return binop(n);
      case "call": return call(n);
    }
  };

  const binop = ({ op, l, r }) => {
    const a = ev(l), b = ev(r);
    chk(a); chk(b);
    switch (op) {
      case "&": return toText(a) + toText(b);
      case "=": return compare(a, b) === 0;
      case "<>": return compare(a, b) !== 0;
      case "<": return compare(a, b) < 0;
      case ">": return compare(a, b) > 0;
      case "<=": return compare(a, b) <= 0;
      case ">=": return compare(a, b) >= 0;
    }
    const x = toNum(a), y = toNum(b);
    switch (op) {
      case "+": return fin(x + y);
      case "-": return fin(x - y);
      case "*": return fin(x * y);
      case "/": return y === 0 ? fail("#DIV/0!") : fin(x / y);
      case "^": return fin(x ** y);
    }
  };

  const cells = (n) => n.addrs.map(lookup);

  // Numbers for SUM-like functions: ranges keep only numbers, direct args convert.
  const numbers = (args) => {
    const out = [];
    for (const a of args) {
      if (a.t === "range") {
        for (const v of cells(a)) {
          chk(v);
          if (typeof v === "number") out.push(v);
        }
      } else out.push(toNum(ev(a)));
    }
    return out;
  };

  const bools = (args) => {
    const out = [];
    for (const a of args) {
      if (a.t === "range") {
        for (const v of cells(a)) if (typeof v === "number" || typeof v === "boolean") out.push(v !== 0 && v !== false);
      } else out.push(toBool(ev(a)));
    }
    return out;
  };

  const texts = (args) => args.map((a) => (a.t === "range" ? cells(a).map(toText).join("") : toText(ev(a)))).join("");

  const arity = (args, min, max) => { if (args.length < min || args.length > max) fail("#VALUE!"); };

  const call = ({ name, args }) => {
    switch (name) {
      case "SUM": return fin(numbers(args).reduce((s, v) => s + v, 0));
      case "AVERAGE": {
        const v = numbers(args);
        return v.length ? fin(v.reduce((s, x) => s + x, 0) / v.length) : fail("#DIV/0!");
      }
      case "MIN": { const v = numbers(args); return v.length ? Math.min(...v) : 0; }
      case "MAX": { const v = numbers(args); return v.length ? Math.max(...v) : 0; }
      case "COUNT": {
        let c = 0;
        for (const a of args) {
          if (a.t === "range") { for (const v of cells(a)) if (typeof v === "number") c++; }
          else if (typeof ev(a) === "number") c++;
        }
        return c;
      }
      case "IF":
        arity(args, 2, 3);
        if (toBool(ev(args[0]))) return ev(args[1]);
        return args.length === 3 ? ev(args[2]) : false;
      case "AND": arity(args, 1, Infinity); return bools(args).every(Boolean);
      case "OR": arity(args, 1, Infinity); return bools(args).some(Boolean);
      case "NOT": arity(args, 1, 1); return !toBool(ev(args[0]));
      case "ROUND": {
        arity(args, 2, 2);
        const x = toNum(ev(args[0])), d = toNum(ev(args[1]));
        return fin(round(x, d));
      }
      case "ABS": arity(args, 1, 1); return Math.abs(toNum(ev(args[0])));
      case "LEN": arity(args, 1, 1); return toText(ev(args[0])).length;
      case "UPPER": arity(args, 1, 1); return toText(ev(args[0])).toUpperCase();
      case "LOWER": arity(args, 1, 1); return toText(ev(args[0])).toLowerCase();
      case "CONCAT": return texts(args);
    }
    return fail("#NAME?");
  };

  try {
    return ev(ast);
  } catch (e) {
    if (e instanceof Fail) return e.code;
    throw e;
  }
}
