import { parseFormula, refsOf, evaluate } from "./formula.mjs";
import { parseAddr, toAddr, compareAddr } from "./addr.mjs";

export function valueOf(raw) {
  if (raw === "" || raw == null) return null;
  const t = raw.trim();
  if (t !== "" && Number.isFinite(Number(t))) return Number(t);
  const u = t.toUpperCase();
  if (u === "TRUE") return true;
  if (u === "FALSE") return false;
  if (raw.startsWith("'")) return raw.slice(1);
  return raw;
}

function expand(ref) {
  if (!ref.includes(":")) return [ref.replace(/\$/g, "").toUpperCase()];
  const [a, b] = ref.split(":").map((r) => parseAddr(r));
  const out = [];
  for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++)
    for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++) out.push(toAddr(c, r));
  return out;
}

// Parses every formula cell and finds its direct precedents among formula cells.
function analyze(sheet) {
  const asts = new Map(), deps = new Map();
  for (const [addr, raw] of sheet.cells) {
    if (!raw.startsWith("=")) continue;
    let ast = null;
    try { ast = parseFormula(raw); } catch { ast = null; }
    asts.set(addr, ast);
    const d = new Set();
    if (ast) for (const ref of refsOf(ast)) for (const a of expand(ref)) d.add(a);
    deps.set(addr, d);
  }
  for (const [addr, d] of deps) for (const a of d) if (!asts.has(a)) d.delete(a);
  return { asts, deps };
}

// Iterative Tarjan: returns SCCs, precedents first.
function sccs(deps) {
  const index = new Map(), low = new Map(), onStack = new Set(), stack = [], out = [];
  let n = 0;
  for (const root of deps.keys()) {
    if (index.has(root)) continue;
    const work = [[root, deps.get(root).values()]];
    index.set(root, n); low.set(root, n++); stack.push(root); onStack.add(root);
    while (work.length) {
      const [v, it] = work[work.length - 1];
      const nx = it.next();
      if (!nx.done) {
        const w = nx.value;
        if (!index.has(w)) {
          index.set(w, n); low.set(w, n++); stack.push(w); onStack.add(w);
          work.push([w, deps.get(w).values()]);
        } else if (onStack.has(w)) low.set(v, Math.min(low.get(v), index.get(w)));
      } else {
        work.pop();
        if (work.length) { const p = work[work.length - 1][0]; low.set(p, Math.min(low.get(p), low.get(v))); }
        if (low.get(v) === index.get(v)) {
          const comp = [];
          let w;
          do { w = stack.pop(); onStack.delete(w); comp.push(w); } while (w !== v);
          out.push(comp);
        }
      }
    }
  }
  return out;
}

const cyclic = (comp, deps) => comp.length > 1 || deps.get(comp[0]).has(comp[0]);

export function computeAll(sheet) {
  const { asts, deps } = analyze(sheet);
  const values = new Map();
  for (const [addr, raw] of sheet.cells) if (!asts.has(addr)) values.set(addr, valueOf(raw));
  const lookup = (a) => values.get(String(a).replace(/\$/g, "").toUpperCase()) ?? null;
  for (const comp of sccs(deps)) {
    if (cyclic(comp, deps)) { for (const a of comp) values.set(a, "#CYCLE!"); continue; }
    const a = comp[0], ast = asts.get(a);
    if (!ast) { values.set(a, "#ERROR!"); continue; }
    let v;
    try { v = evaluate(ast, lookup); } catch { v = "#ERROR!"; }
    values.set(a, v);
  }
  return values;
}

export function dependents(sheet, addr) {
  const { deps } = analyze(sheet);
  const start = toAddr(parseAddr(addr).col, parseAddr(addr).row);
  const rev = new Map();
  for (const [a, d] of deps) for (const p of d) {
    if (!rev.has(p)) rev.set(p, []);
    rev.get(p).push(a);
  }
  const seen = new Set(), todo = [start];
  while (todo.length) for (const a of rev.get(todo.pop()) ?? []) if (!seen.has(a)) { seen.add(a); todo.push(a); }
  seen.delete(start);
  for (const comp of sccs(deps)) if (cyclic(comp, deps)) for (const a of comp) seen.delete(a);
  const order = [...seen].sort(compareAddr);
  const rank = new Map(order.map((a, i) => [a, i]));
  const indeg = new Map(), next = new Map();
  for (const a of order) {
    let k = 0;
    for (const p of deps.get(a)) if (seen.has(p)) {
      k++;
      if (!next.has(p)) next.set(p, []);
      next.get(p).push(a);
    }
    indeg.set(a, k);
  }
  // min-heap of ranks
  const heap = [];
  const push = (x) => {
    heap.push(x);
    for (let i = heap.length - 1; i > 0;) {
      const p = (i - 1) >> 1;
      if (heap[p] <= heap[i]) break;
      [heap[p], heap[i]] = [heap[i], heap[p]]; i = p;
    }
  };
  const pop = () => {
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      for (let i = 0; ;) {
        let m = i;
        for (const c of [2 * i + 1, 2 * i + 2]) if (c < heap.length && heap[c] < heap[m]) m = c;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
      }
    }
    return top;
  };
  for (const a of order) if (indeg.get(a) === 0) push(rank.get(a));
  const out = [];
  while (heap.length) {
    const a = order[pop()];
    out.push(a);
    for (const b of next.get(a) ?? []) {
      indeg.set(b, indeg.get(b) - 1);
      if (indeg.get(b) === 0) push(rank.get(b));
    }
  }
  return out;
}
