import { parseAddr, toAddr, colIndex } from "./addr.mjs";
import { getCell, setCell } from "./sheet.mjs";
import { valueOf } from "./recalc.mjs";

const typeRank = (v) => (typeof v === "number" ? 0 : typeof v === "string" ? 1 : 2);

// Orders non-empty values: numbers, strings (case-insensitive), booleans.
function compareValues(a, b) {
  const ra = typeRank(a), rb = typeRank(b);
  if (ra !== rb) return ra - rb;
  if (ra === 1) { const x = a.toLowerCase(), y = b.toLowerCase(); return x < y ? -1 : x > y ? 1 : 0; }
  return a < b ? -1 : a > b ? 1 : 0;
}

function bounds(range) {
  const [a, b] = range.split(":").map(parseAddr);
  return { c1: Math.min(a.col, b.col), c2: Math.max(a.col, b.col), r1: Math.min(a.row, b.row), r2: Math.max(a.row, b.row) };
}

export function sortRange(sheet, range, keys, options = {}) {
  const { c1, c2, r1, r2 } = bounds(range);
  const start = options.header ? r1 + 1 : r1;
  const rows = [];
  for (let r = start; r <= r2; r++) {
    const raws = [];
    for (let c = c1; c <= c2; c++) raws.push(getCell(sheet, toAddr(c, r)));
    rows.push(raws);
  }
  const ks = keys.map((k) => ({ i: colIndex(k.col) - c1, desc: !!k.desc }));
  const cmp = (x, y) => {
    for (const { i, desc } of ks) {
      const a = valueOf(x[i]), b = valueOf(y[i]);
      if (a == null || b == null) {
        if (a == null && b == null) continue;
        return a == null ? 1 : -1;
      }
      const d = compareValues(a, b);
      if (d) return desc ? -d : d;
    }
    return 0;
  };
  rows.sort(cmp);
  rows.forEach((raws, k) => raws.forEach((raw, j) => setCell(sheet, toAddr(c1 + j, start + k), raw)));
}

export function pivot(values, range, { rows, value, agg }) {
  const { c1, c2, r1, r2 } = bounds(range);
  const findCol = (name) => {
    for (let c = c1; c <= c2; c++) if (values.get(toAddr(c, r1)) === name) return c;
    throw new Error(`no such column: ${name}`);
  };
  const kc = findCol(rows), vc = findCol(value);
  const groups = new Map();
  for (let r = r1 + 1; r <= r2; r++) {
    const k = values.get(toAddr(kc, r)) ?? null;
    const id = k === null ? "b" : `${typeof k}:${k}`;
    if (!groups.has(id)) groups.set(id, { key: k, vals: [] });
    groups.get(id).vals.push(values.get(toAddr(vc, r)) ?? null);
  }
  const aggregate = (vals) => {
    if (agg === "count") return vals.filter((v) => v !== null).length;
    const nums = vals.filter((v) => typeof v === "number");
    if (agg === "sum") return nums.reduce((s, n) => s + n, 0);
    if (!nums.length) return null;
    if (agg === "avg") return nums.reduce((s, n) => s + n, 0) / nums.length;
    if (agg === "min") return nums.reduce((m, n) => (n < m ? n : m));
    if (agg === "max") return nums.reduce((m, n) => (n > m ? n : m));
    throw new Error(`unknown aggregate: ${agg}`);
  };
  const all = [...groups.values()];
  const blank = all.find((g) => g.key === null);
  const rest = all.filter((g) => g.key !== null).sort((a, b) => compareValues(a.key, b.key));
  if (blank) rest.push({ key: "(blank)", vals: blank.vals });
  return rest.map((g) => ({ key: g.key, value: aggregate(g.vals) }));
}
