// Subset of spreadsheet number formats.

function splitSections(pattern) {
  const out = [];
  let cur = "";
  let quoted = false;
  for (let i = 0; i < pattern.length; i++) {
    const c = pattern[i];
    if (quoted) {
      cur += c;
      if (c === '"') quoted = false;
    } else if (c === '"') {
      quoted = true;
      cur += c;
    } else if (c === "\\" && i + 1 < pattern.length) {
      cur += c + pattern[++i];
    } else if (c === ";") {
      out.push(cur);
      cur = "";
    } else cur += c;
  }
  out.push(cur);
  return out;
}

function tokenize(section) {
  const toks = [];
  for (let i = 0; i < section.length; i++) {
    const c = section[i];
    if (c === '"') {
      const end = section.indexOf('"', i + 1);
      const stop = end < 0 ? section.length : end;
      toks.push({ t: "lit", v: section.slice(i + 1, stop) });
      i = stop;
    } else if (c === "\\") {
      if (i + 1 < section.length) toks.push({ t: "lit", v: section[++i] });
    } else if (c === "0" || c === "#") toks.push({ t: "d", v: c });
    else if (c === "." || c === "," || c === "%") toks.push({ t: c });
    else if ((c === "E" || c === "e") && /^[Ee][+-]0+/.test(section.slice(i))) {
      const m = /^[Ee]([+-])(0+)/.exec(section.slice(i));
      toks.push({ t: "exp", plus: m[1] === "+", n: m[2].length });
      i += m[0].length - 1;
    } else toks.push({ t: "lit", v: c });
  }
  return toks;
}

// Plain decimal digits of a non-negative number as JS prints it.
function decimal(abs, shift) {
  const m = /^(\d+)(?:\.(\d+))?(?:e([+-]\d+))?$/.exec(String(abs));
  const digits = m[1] + (m[2] || "");
  return { digits, point: m[1].length + Number(m[3] || 0) + shift };
}

function split({ digits, point }) {
  if (point <= 0) return ["0", "0".repeat(-point) + digits];
  if (point >= digits.length) return [digits + "0".repeat(point - digits.length), ""];
  return [digits.slice(0, point), digits.slice(point)];
}

// Round a digit string to `keep` digits, half up (magnitudes are non-negative).
function roundTo(s, keep) {
  if (s.length <= keep) return s.padEnd(keep, "0");
  let r = s.slice(0, keep);
  if (s[keep] >= "5") {
    const n = (BigInt(r || "0") + 1n).toString().padStart(keep, "0");
    r = n;
  }
  return r;
}

function group(s) {
  return s.replace(/\B(?=(\d{3})+$)/g, ",");
}

function formatSection(abs, toks) {
  const pct = toks.some((t) => t.t === "%");
  const dec = decimal(abs, pct ? 2 : 0);
  const expTok = toks.find((t) => t.t === "exp");
  const intKinds = [];
  const decKinds = [];
  let seenDot = false;
  let comma = false;
  let last = -1;
  toks.forEach((t, i) => {
    if (t.t === "d") {
      (seenDot ? decKinds : intKinds).push(t.v);
      last = i;
    } else if (t.t === ".") seenDot = true;
    else if (t.t === "," && !seenDot && intKinds.length) comma = true;
  });
  const hasDot = seenDot;
  const n = decKinds.length;
  const stripKinds = (frac) => {
    let end = frac.length;
    while (end > 0 && decKinds[end - 1] === "#" && frac[end - 1] === "0") end--;
    return frac.slice(0, end);
  };

  let num;
  if (expTok) {
    const lead = dec.digits.match(/^0*/)[0].length;
    let sig = dec.digits.slice(lead);
    let exp = sig ? dec.point - lead - 1 : 0;
    if (!sig) sig = "0";
    const keep = 1 + n;
    let r = roundTo(sig, keep);
    if (r.length > keep) {
      exp++;
      r = r.slice(0, keep);
    }
    const frac = stripKinds(r.slice(1));
    num = r[0] + (hasDot ? "." + frac : "");
    const sign = exp < 0 ? "-" : expTok.plus ? "+" : "";
    num += "E" + sign + String(Math.abs(exp)).padStart(expTok.n, "0");
  } else {
    let [ip, fp] = split(dec);
    const all = roundTo(ip + fp, ip.length + n);
    // roundTo may carry into an extra digit
    const ilen = all.length - n;
    ip = all.slice(0, ilen).replace(/^0+/, "");
    fp = all.slice(ilen);
    ip = ip.padStart(intKinds.filter((k) => k === "0").length, "0");
    if (comma) ip = group(ip);
    num = ip + (hasDot ? "." + stripKinds(fp) : "");
  }

  let out = "";
  let done = false;
  toks.forEach((t, i) => {
    if (t.t === "lit") out += t.v;
    else if (t.t === "%") out += "%";
    else if (!done && (t.t === "d" || t.t === "exp")) {
      out += num;
      done = true;
    }
  });
  if (!done) out += num === "0" ? "" : "";
  return out;
}

export function formatNumber(value, pattern) {
  if (typeof value !== "number") {
    if (value === null || value === undefined) return "";
    if (typeof value === "boolean") return value ? "TRUE" : "FALSE";
    return String(value);
  }
  if (pattern === "General" || !Number.isFinite(value)) return String(value);
  const secs = splitSections(pattern);
  let idx = 0;
  if (secs.length === 2) idx = value < 0 ? 1 : 0;
  else if (secs.length >= 3) idx = value < 0 ? 1 : value === 0 ? 2 : 0;
  const own = secs.length > 1 && value < 0;
  const text = formatSection(Math.abs(value), tokenize(secs[idx]));
  if (!own && value < 0 && /[1-9]/.test(numericPart(text, secs[idx]))) return "-" + text;
  return text;
}

// Digits that appear in the formatted output come only from the number unless
// the pattern has literal digits (quoted); good enough for the zero check.
function numericPart(text, section) {
  const lits = tokenize(section).filter((t) => t.t === "lit").map((t) => t.v).join("");
  let s = text;
  for (const ch of lits) s = s.replace(ch, "");
  return s;
}
